package in.schemesathi.eligibility;

import in.schemesathi.profile.CitizenProfile;import in.schemesathi.profile.CitizenProfileRepository;import in.schemesathi.scheme.*;
import com.fasterxml.jackson.databind.JsonNode;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class EligibilityService{
 private final CitizenProfileRepository profiles;private final SchemeRepository schemes;
 public EligibilityService(CitizenProfileRepository profiles,SchemeRepository schemes){this.profiles=profiles;this.schemes=schemes;}
 public EligibilityDtos.Assessment assess(UUID userId,UUID schemeId){CitizenProfile p=profiles.findById(userId).orElseThrow(()->new IllegalArgumentException("Complete your citizen profile first"));GovernmentScheme s=schemes.findById(schemeId).orElseThrow(()->new IllegalArgumentException("Scheme not found"));if(!s.isPublished()||!"APPROVED".equals(s.getReviewStatus()))throw new IllegalArgumentException("Scheme is not publicly available");
  List<String> matched=new ArrayList<>(),unmet=new ArrayList<>(),missing=new ArrayList<>();JsonNode rules=s.getEligibilityRules();JsonNode all=rules.path("all");for(JsonNode c:all)check(c,p,matched,unmet,missing);
  JsonNode any=rules.path("any");if(any.isArray()&&!any.isEmpty()){List<String> aMatch=new ArrayList<>(),aUnmet=new ArrayList<>(),aMissing=new ArrayList<>();boolean anyPass=false;for(JsonNode c:any){List<String> m=new ArrayList<>(),u=new ArrayList<>(),mi=new ArrayList<>();check(c,p,m,u,mi);if(u.isEmpty()&&mi.isEmpty())anyPass=true;aMatch.addAll(m);aUnmet.addAll(u);aMissing.addAll(mi);}if(anyPass)matched.add("At least one alternative eligibility condition is satisfied");else if(!aMissing.isEmpty())missing.addAll(aMissing);else unmet.add("None of the alternative eligibility conditions are satisfied");}
  String status=!unmet.isEmpty()?"NOT_ELIGIBLE":!missing.isEmpty()?"NEEDS_INFORMATION":"ELIGIBLE";return new EligibilityDtos.Assessment(s.getId(),s.getTitle(),status,matched,unmet,missing,"Preliminary assessment only. Final eligibility is decided by the scheme's implementing department; verify current official guidelines.");}
 private void check(JsonNode c,CitizenProfile p,List<String> matched,List<String> unmet,List<String> missing){String field=c.path("field").asText(),op=c.path("operator").asText("EQ");JsonNode value=c.path("value");Object actual=fieldValue(field,p);String label=c.path("label").asText(field);
  if(actual==null){missing.add("Please provide: "+label);return;}boolean pass=false;try{if(actual instanceof Number n&&value.isNumber()){double x=n.doubleValue(),y=value.asDouble();pass=switch(op){case "LTE"->x<=y;case "LT"->x<y;case "GTE"->x>=y;case "GT"->x>y;case "EQ"->Double.compare(x,y)==0;case "NEQ"->Double.compare(x,y)!=0;default->false;};}else{String x=String.valueOf(actual),y=value.asText();pass=switch(op){case "EQ"->x.equalsIgnoreCase(y);case "NEQ"->!x.equalsIgnoreCase(y);case "IN"->{boolean found=false;for(JsonNode item:value)if(x.equalsIgnoreCase(item.asText()))found=true;yield found;}case "CONTAINS"->x.toLowerCase().contains(y.toLowerCase());default->false;};}}catch(Exception ignored){}
  String text=c.path("description").asText(label+" "+op+" "+value.asText());if(pass)matched.add(text);else unmet.add(text);
 }
 private Object fieldValue(String f,CitizenProfile p){return switch(f){case "age"->p.getDateOfBirth()==null?null:Period.between(p.getDateOfBirth(),LocalDate.now()).getYears();case "annualIncome"->p.getAnnualIncome();case "stateCode"->p.getStateCode();case "gender"->p.getGender();case "maritalStatus"->p.getMaritalStatus();case "employmentStatus"->p.getEmploymentStatus();case "educationLevel"->p.getEducationLevel();case "socialCategory"->p.getSocialCategory();case "residenceType"->p.getResidenceType();case "disability"->p.getDisability();default->null;};}
}
